#include "l2_state.h"

#include <limits.h>
#include <string.h>

static uint16_t sat16(uint16_t value){return value==UINT16_MAX?value:(uint16_t)(value+1U);}
static uint32_t sat32(uint32_t value){return value==UINT32_MAX?value:value+1U;}
static void abort_session(L2State *s){if(s->session_open)s->aborted_sessions=sat32(s->aborted_sessions);s->session_open=0;s->pending_count=0;s->pending_workspace=0;s->context=L2_CONTEXT_TRANSITION;s->context_valid=0;}
static void clear_memory(L2State *s){memset(s->nodes,0,sizeof(s->nodes));memset(s->edges,0,sizeof(s->edges));memset(s->triples,0,sizeof(s->triples));memset(s->workspaces,0,sizeof(s->workspaces));memset(s->pending_roles,0,sizeof(s->pending_roles));s->pending_count=0;s->pending_workspace=0;s->session_open=0;s->context_valid=0;s->context=L2_CONTEXT_UNKNOWN;s->context_ms=0;s->completed_session_generation=0;s->invalid_events=0;s->aborted_sessions=0;}
void l2_init(L2State *s){if(s){memset(s,0,sizeof(*s));s->expected_seq=1;s->context=L2_CONTEXT_UNKNOWN;}}

static int node_cmp(const L2Node *a,const L2Node *b){if(a->count!=b->count)return a->count<b->count?-1:1;if(a->last_generation!=b->last_generation)return a->last_generation<b->last_generation?-1:1;if(a->workspace!=b->workspace)return a->workspace<b->workspace?-1:1;return a->role<b->role?-1:a->role>b->role;}
static int edge_cmp(const L2Edge *a,const L2Edge *b){if(a->count!=b->count)return a->count<b->count?-1:1;if(a->last_generation!=b->last_generation)return a->last_generation<b->last_generation?-1:1;if(a->workspace!=b->workspace)return a->workspace<b->workspace?-1:1;if(a->from_role!=b->from_role)return a->from_role<b->from_role?-1:1;return a->to_role<b->to_role?-1:a->to_role>b->to_role;}
static int triple_cmp(const L2Triple *a,const L2Triple *b){if(a->count!=b->count)return a->count<b->count?-1:1;if(a->last_generation!=b->last_generation)return a->last_generation<b->last_generation?-1:1;const uint8_t aa[4]={a->workspace,a->r1,a->r2,a->r3},bb[4]={b->workspace,b->r1,b->r2,b->r3};for(size_t i=0;i<4;i++)if(aa[i]!=bb[i])return aa[i]<bb[i]?-1:1;return 0;}
static L2Node *node_slot(L2State *s,uint8_t w,uint8_t role){size_t empty=L2_NODE_CAP,victim=0;bool victim_set=false;for(size_t i=0;i<L2_NODE_CAP;i++){if(s->nodes[i].used&&s->nodes[i].workspace==w&&s->nodes[i].role==role)return &s->nodes[i];if(!s->nodes[i].used){if(empty==L2_NODE_CAP)empty=i;continue;}if(!victim_set||node_cmp(&s->nodes[i],&s->nodes[victim])<0){victim=i;victim_set=true;}}return empty<L2_NODE_CAP?&s->nodes[empty]:&s->nodes[victim];}
static L2Edge *edge_slot(L2State *s,uint8_t w,uint8_t from,uint8_t to){size_t empty=L2_EDGE_CAP,victim=0;bool victim_set=false;for(size_t i=0;i<L2_EDGE_CAP;i++){if(s->edges[i].used&&s->edges[i].workspace==w&&s->edges[i].from_role==from&&s->edges[i].to_role==to)return &s->edges[i];if(!s->edges[i].used){if(empty==L2_EDGE_CAP)empty=i;continue;}if(!victim_set||edge_cmp(&s->edges[i],&s->edges[victim])<0){victim=i;victim_set=true;}}return empty<L2_EDGE_CAP?&s->edges[empty]:&s->edges[victim];}
static L2Triple *triple_slot(L2State *s,uint8_t w,uint8_t a,uint8_t b,uint8_t c){size_t empty=L2_TRIPLE_CAP,victim=0;bool victim_set=false;for(size_t i=0;i<L2_TRIPLE_CAP;i++){if(s->triples[i].used&&s->triples[i].workspace==w&&s->triples[i].r1==a&&s->triples[i].r2==b&&s->triples[i].r3==c)return &s->triples[i];if(!s->triples[i].used){if(empty==L2_TRIPLE_CAP)empty=i;continue;}if(!victim_set||triple_cmp(&s->triples[i],&s->triples[victim])<0){victim=i;victim_set=true;}}return empty<L2_TRIPLE_CAP?&s->triples[empty]:&s->triples[victim];}
static void add_node(L2State *s,uint8_t w,uint8_t role){L2Node *x=node_slot(s,w,role);if(!x->used||x->workspace!=w||x->role!=role){memset(x,0,sizeof(*x));x->used=1;x->workspace=w;x->role=role;}x->count=sat16(x->count);x->last_generation=s->completed_session_generation;}
static void add_edge(L2State *s,uint8_t w,uint8_t a,uint8_t b){L2Edge *x=edge_slot(s,w,a,b);if(!x->used||x->workspace!=w||x->from_role!=a||x->to_role!=b){memset(x,0,sizeof(*x));x->used=1;x->workspace=w;x->from_role=a;x->to_role=b;}x->count=sat16(x->count);x->last_generation=s->completed_session_generation;}
static void add_triple(L2State *s,uint8_t w,uint8_t a,uint8_t b,uint8_t c){L2Triple *x=triple_slot(s,w,a,b,c);if(!x->used||x->workspace!=w||x->r1!=a||x->r2!=b||x->r3!=c){memset(x,0,sizeof(*x));x->used=1;x->workspace=w;x->r1=a;x->r2=b;x->r3=c;}x->count=sat16(x->count);x->last_generation=s->completed_session_generation;}
static void age(L2State *s){for(size_t i=0;i<L2_NODE_CAP;i++)if(s->nodes[i].used&&(s->nodes[i].count/=2U)==0)memset(&s->nodes[i],0,sizeof(s->nodes[i]));for(size_t i=0;i<L2_EDGE_CAP;i++)if(s->edges[i].used&&(s->edges[i].count/=2U)==0)memset(&s->edges[i],0,sizeof(s->edges[i]));for(size_t i=0;i<L2_TRIPLE_CAP;i++)if(s->triples[i].used&&(s->triples[i].count/=2U)==0)memset(&s->triples[i],0,sizeof(s->triples[i]));for(size_t i=0;i<L2_WORKSPACES;i++){s->workspaces[i].completed_sessions/=2U;s->workspaces[i].accepted_transitions/=2U;}}
static void commit_session(L2State *s){uint8_t w=s->pending_workspace;L2Workspace *ws=&s->workspaces[w-1U];s->completed_session_generation=sat32(s->completed_session_generation);ws->completed_sessions=sat16(ws->completed_sessions);for(size_t i=0;i<s->pending_count;i++)add_node(s,w,s->pending_roles[i]);for(size_t i=0;i+1U<s->pending_count;i++){add_edge(s,w,s->pending_roles[i],s->pending_roles[i+1U]);ws->accepted_transitions=sat16(ws->accepted_transitions);}for(size_t i=0;i+2U<s->pending_count;i++)add_triple(s,w,s->pending_roles[i],s->pending_roles[i+1U],s->pending_roles[i+2U]);if(s->completed_session_generation%16U==0U)age(s);}

static bool better_triple(const L2Triple *a,const L2Triple *b){if(!b)return true;if(a->count!=b->count)return a->count>b->count;if(a->r1!=b->r1)return a->r1<b->r1;if(a->r2!=b->r2)return a->r2<b->r2;return a->r3<b->r3;}
L2QueryResult l2_query_workspace(const L2State *s,uint8_t w,uint64_t now){L2QueryResult r;memset(&r,0,sizeof(r));r.workspace=w;r.context=s?s->context:L2_CONTEXT_UNKNOWN;if(!s||w<1||w>4){r.reason=L2_REASON_INVALID_CONTEXT;return r;}if(!s->context_valid||now<s->context_ms||now-s->context_ms>60000U){r.reason=L2_REASON_STALE_CONTEXT;return r;}const L2Workspace *ws=&s->workspaces[w-1U];r.completed_sessions=ws->completed_sessions;r.accepted_transitions=ws->accepted_transitions;const L2Triple *best=NULL;for(size_t i=0;i<L2_TRIPLE_CAP;i++)if(s->triples[i].used&&s->triples[i].workspace==w&&s->triples[i].count>=2U&&better_triple(&s->triples[i],best))best=&s->triples[i];if(ws->completed_sessions<3U||ws->accepted_transitions<6U||!best){r.reason=L2_REASON_WARMING_UP;return r;}if(s->context==L2_CONTEXT_RESOURCE_CONSTRAINED){r.status=L2_RESULT_BLOCKED;r.reason=L2_REASON_RESOURCE_CONSTRAINED;return r;}if(s->context==L2_CONTEXT_UNKNOWN||s->context==L2_CONTEXT_TRANSITION){r.reason=L2_REASON_INVALID_CONTEXT;return r;}r.status=L2_RESULT_CANDIDATE;r.roles[0]=(L2Role)best->r1;r.roles[1]=(L2Role)best->r2;r.roles[2]=(L2Role)best->r3;r.triple_count=best->count;r.requires_user_approval=true;return r;}

static bool event_basic_valid(const L2Event *e){if(!e||!e->simulated||e->workspace>4U||e->quality>L2_QUALITY_RESET||e->kind>L2_EVENT_RESET||e->role>L2_ROLE_OTHER||e->activity>L2_ACTIVITY_UNKNOWN||e->condition>L2_CONDITION_UNRELIABLE)return false;if(e->kind==L2_EVENT_SESSION_BEGIN||e->kind==L2_EVENT_SESSION_END)return e->workspace>0&&e->role==L2_ROLE_NONE&&e->activity==L2_ACTIVITY_NONE&&e->condition==L2_CONDITION_NONE;if(e->kind==L2_EVENT_ROLE)return e->workspace>0&&e->role!=L2_ROLE_NONE&&e->activity==L2_ACTIVITY_NONE&&e->condition==L2_CONDITION_NONE;if(e->kind==L2_EVENT_CONTEXT)return e->role==L2_ROLE_NONE&&e->activity!=L2_ACTIVITY_NONE&&e->condition!=L2_CONDITION_NONE;if(e->kind==L2_EVENT_QUERY)return e->workspace>0&&e->role==L2_ROLE_NONE&&e->activity==L2_ACTIVITY_NONE&&e->condition==L2_CONDITION_NONE;if(e->kind==L2_EVENT_GAP||e->kind==L2_EVENT_RESET)return e->workspace==0&&e->role==L2_ROLE_NONE&&e->activity==L2_ACTIVITY_NONE&&e->condition==L2_CONDITION_NONE;return false;}
L2StepStatus l2_step(L2State *s,const L2Event *e,L2QueryResult *result){if(!s)return L2_STEP_REJECTED;if(!event_basic_valid(e)){s->invalid_events=sat32(s->invalid_events);abort_session(s);return L2_STEP_REJECTED;}if(s->reserved[0]||e->seq!=s->expected_seq){abort_session(s);return L2_STEP_REJECTED;}if(e->seq==UINT64_MAX)s->reserved[0]=1;else s->expected_seq=e->seq+1U;if(e->quality==L2_QUALITY_ABSENT||e->quality==L2_QUALITY_INVALID){s->invalid_events=sat32(s->invalid_events);abort_session(s);return L2_STEP_INVALID_QUALITY;}if((e->quality==L2_QUALITY_RESET)!=(e->kind==L2_EVENT_RESET)){abort_session(s);return L2_STEP_REJECTED;}if(s->stream_initialized&&e->monotonic_ms<=s->last_valid_ms){abort_session(s);return L2_STEP_REJECTED;}if(s->stream_initialized&&e->monotonic_ms-s->last_valid_ms>60000U)abort_session(s);s->last_valid_ms=e->monotonic_ms;s->stream_initialized=1;if(e->kind==L2_EVENT_RESET){uint64_t next=s->expected_seq,last=e->monotonic_ms;uint8_t exhausted=s->reserved[0];clear_memory(s);s->expected_seq=next;s->reserved[0]=exhausted;s->last_valid_ms=last;s->stream_initialized=1;return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_GAP){abort_session(s);return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_CONTEXT){if(e->condition==L2_CONDITION_UNKNOWN||e->condition==L2_CONDITION_UNRELIABLE||e->activity==L2_ACTIVITY_UNKNOWN)s->context=L2_CONTEXT_UNKNOWN;else if(e->condition>=L2_CONDITION_CPU_PRESSURE&&e->condition<=L2_CONDITION_MIXED_PRESSURE)s->context=L2_CONTEXT_RESOURCE_CONSTRAINED;else if(e->condition==L2_CONDITION_QUIET){const L2Context map[]={L2_CONTEXT_UNKNOWN,L2_CONTEXT_IDLE,L2_CONTEXT_FOCUSED,L2_CONTEXT_BACKGROUND_BUSY,L2_CONTEXT_MULTI_TASK,L2_CONTEXT_UNKNOWN};s->context=map[e->activity];}else{abort_session(s);return L2_STEP_REJECTED;}s->context_ms=e->monotonic_ms;s->context_valid=1;return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_SESSION_BEGIN){if(s->session_open){abort_session(s);return L2_STEP_REJECTED;}s->session_open=1;s->pending_workspace=e->workspace;s->pending_count=0;return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_ROLE){if(!s->session_open||s->pending_workspace!=e->workspace){abort_session(s);return L2_STEP_REJECTED;}if(s->pending_count>=L2_PENDING_CAP){abort_session(s);return L2_STEP_REJECTED;}s->pending_roles[s->pending_count++]=(uint8_t)e->role;return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_SESSION_END){if(!s->session_open||s->pending_workspace!=e->workspace){abort_session(s);return L2_STEP_REJECTED;}if(s->pending_count>=3U)commit_session(s);else s->aborted_sessions=sat32(s->aborted_sessions);s->session_open=0;s->pending_count=0;s->pending_workspace=0;return L2_STEP_ACCEPTED;}if(e->kind==L2_EVENT_QUERY){if(s->session_open)abort_session(s);if(result)*result=l2_query_workspace(s,e->workspace,e->monotonic_ms);return L2_STEP_QUERY_RESULT;}abort_session(s);return L2_STEP_REJECTED;}

const char *l2_role_name(L2Role x){static const char *const n[]={"NONE","CODE_EDIT","BUILD_TEST","DOC_VIEW","REFERENCES","CANVAS","ASSET_GROUP","EXPORT","OTHER"};return x<=L2_ROLE_OTHER?n[x]:"INVALID";}
const char *l2_context_name(L2Context x){static const char *const n[]={"UNKNOWN","IDLE","FOCUSED","MULTI_TASK","BACKGROUND_BUSY","RESOURCE_CONSTRAINED","TRANSITION"};return x<=L2_CONTEXT_TRANSITION?n[x]:"INVALID";}
const char *l2_result_name(L2ResultStatus x){static const char *const n[]={"NONE","CANDIDATE","BLOCKED"};return x<=L2_RESULT_BLOCKED?n[x]:"INVALID";}
const char *l2_reason_name(L2Reason x){static const char *const n[]={"NONE","WARMING_UP","STALE_CONTEXT","INVALID_CONTEXT","RESOURCE_CONSTRAINED"};return x<=L2_REASON_RESOURCE_CONSTRAINED?n[x]:"INVALID";}
